"""Multi-pass 제안서 생성 — Outline → 슬라이드별 도형 JSON → 병합.

설계 의도:
  Single-pass 한계:
    - max_tokens=16000 토큰을 30 슬라이드로 나누면 슬라이드당 ~530 토큰
    - AI 가 토큰 절약 모드 → 빈약한 본문
  Multi-pass 해법:
    - Phase 1: 가벼운 outline 호출 1번 (~5k 토큰)
    - Phase 2: 슬라이드마다 16k 토큰 풀로 도형 JSON 호출 (병렬)
    - Phase 3: 병합 → generate_from_shape_json 그대로 호출
  이러면 슬라이드당 도형 50~80개 빽빽하게 가능.

병렬 처리:
  asyncio.gather() 로 5장씩 묶어서 호출 (Anthropic rate limit 고려).
  실패 슬라이드는 placeholder 슬라이드로 대체 (전체 실패 X).

진행률:
  orchestrate() 가 async generator → SSE 로 실시간 yield.

비용 예상 (Sonnet 4):
  - Phase 1: ~$0.03 (outline)
  - Phase 2: 슬라이드 30장 × ~$0.02 = ~$0.60
  - 합계: ~$0.65 (single-pass ~$0.05 의 13배)
"""
from __future__ import annotations

import asyncio
import json
import logging
import os
import random
import re
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import AsyncIterator, Optional

log = logging.getLogger("multi_pass")


# ─── Spec Strategy-Step1~3 — 전략 관통 기능 전체 on/off ─────────────
# False = 기존과 100% 동일 (전략 수립/반영/주입 전부 skip).
#   · 단계1(신설): generate_strategy 호출 skip → OutlineResult.strategy = {} 만 실림
#   · 단계2(후속): OUTLINE 프롬프트에 strategy 반영 skip
#   · 단계3(후속): SLIDE 프롬프트에 strategy 주입 skip
# True 로 켜야만 전략 수립 LLM 호출 발생. 사고 시 False 로 즉시 원복.
STRATEGY_INJECTION_ENABLED = True


# ─── Spec Research-Inject — 근거 자료(과업 리서치) SLIDE 주입 on/off ────
# strategy 와 별개 기능 — 독립 플래그로 조합 가능 (strategy off + research on 등).
# False = 기존 100% 동일 (outline.research={} 만 실림, SLIDE 주입 skip).
# True 시: align 페이지 SLIDE 프롬프트에 검증 사실(subject_facts /
#   past_editions / context / summary / sources) 주입 → 본론이 근거 기반으로 깊어짐.
#   ★ inspiration 필드는 제외 (영감 재료, 사실 아님 — 팩트 게이트 정합).
RESEARCH_INJECTION_ENABLED = True


