                "  · 상단 거버닝 + 하단 카드 대칭 나열 (결론 없음) → hero_cards\n"
                "  · conclusion_cards 는 \"3개 축 + 하단으로 수렴하는 결론\"이 본질. 결론 문장이 없으면 이 패턴 아님.\n"
                "\n"
                "★ slide JSON 출력에 반드시 다음 키 포함:\n"
                '  · "preset": "conclusion_cards"  (필수)\n'
